import{_ as a,o as i,c as r,ai as t}from"./chunks/framework.B-VUnR03.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"docs/CHANGELOG.md","filePath":"docs/CHANGELOG.md"}'),n={name:"docs/CHANGELOG.md"};function o(l,e,s,d,h,c){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><p>Noteworthy changes</p><h2 id="_2026-01-02" tabindex="-1">2026-01-02 <a class="header-anchor" href="#_2026-01-02" aria-label="Permalink to “2026-01-02”">​</a></h2><p>Finally offloaded callback works.</p><p>On some context-less operations, it is possible to provide a callback, but previous implementation of that wasn&#39;t async at all.</p><p>Mow it is.</p><p>Event monitoring, however, can&#39;t be easily implemented using just v8 + nan. To deliver true callback monitoring will demand migration to napi.</p><p>It worths a minor release anyway, and 2.x version will born in napi to get it solved properly.</p><h2 id="_2025-06-14" tabindex="-1">2025-06-14 <a class="header-anchor" href="#_2025-06-14" aria-label="Permalink to “2025-06-14”">​</a></h2><p>Finally a decent and more realistic autocomplete is implemented. I&#39;ve got the typescript configuration done right, added a (thin) javascript layer to receive jsdocs and boom! proper autocomplete, documentation snippets and so on.</p><p>Still facing trouble to test on proper real hardware, all my boards are dead or dying, but gpio-sim on (virtualized) fedora 38 is holding things together.</p><h2 id="_2024-06-30" tabindex="-1">2024-06-30 <a class="header-anchor" href="#_2024-06-30" aria-label="Permalink to “2024-06-30”">​</a></h2><ul><li>closed the oldest issue, issue #4, covered it with a specific test case</li><li>recomissioned chai. it must be v4 since it&#39;s a commonsjs project. more info <a href="https://github.com/chaijs/chai/issues/1561#issuecomment-1871878274" target="_blank" rel="noreferrer">here</a>.</li><li>CI/CD still broken, but if i self-host maybe i can get it working! time to homelab again!</li></ul><h2 id="_2024-06-29" tabindex="-1">2024-06-29 <a class="header-anchor" href="#_2024-06-29" aria-label="Permalink to “2024-06-29”">​</a></h2><ul><li>acquired an [raxda rock 3c][<a href="https://radxa.com/products/rock3/3c/" target="_blank" rel="noreferrer">https://radxa.com/products/rock3/3c/</a>] so i can test on real hardware again. my rasp collection is aging and isn&#39;t reliable anymore.</li><li>did a fedora38 virtual machine and to my happy surprise this version has the gpio-sim kernel module built and offers libgpiod 1.6.4! best of two worlds.</li><li>github CI remains unable to run testsuite sadly, tweaked the yaml script to use a fedora 38 container but it&#39;s just not the same thing.</li><li>on the plus side, thanks to the working gpio-sim on my dev environment i could finally cover everything already implemented quite fast. time to look at the issues and missing functions, notably bulk and watch operations.</li></ul><h2 id="_2024-04-20" tabindex="-1">2024-04-20 <a class="header-anchor" href="#_2024-04-20" aria-label="Permalink to “2024-04-20”">​</a></h2><h2 id="_0-4-3" tabindex="-1">0.4.3 <a class="header-anchor" href="#_0-4-3" aria-label="Permalink to “0.4.3”">​</a></h2><ul><li>added a more expressive message in exceptions, bubbling the <a href="https://en.wikipedia.org/wiki/Errno.h" target="_blank" rel="noreferrer">errno</a> value in message of thrown exception, many thanks to @splitice</li></ul><h2 id="_2024-04-06" tabindex="-1">2024-04-06 <a class="header-anchor" href="#_2024-04-06" aria-label="Permalink to “2024-04-06”">​</a></h2><h2 id="_0-4-2" tabindex="-1">0.4.2 <a class="header-anchor" href="#_0-4-2" aria-label="Permalink to “0.4.2”">​</a></h2><ul><li>adding compile flag so the wrapper work again with older libgpiod versions. thanks @alejandroclaro and @splitice for the report, guidance and time.</li><li>working on docs to make people aware of api breaking even inside 1.x series of libgpiod.</li><li>working on script to simulate mockup somehow</li></ul><h2 id="_2024-03-29" tabindex="-1">2024-03-29 <a class="header-anchor" href="#_2024-03-29" aria-label="Permalink to “2024-03-29”">​</a></h2><h2 id="_0-4-1" tabindex="-1">0.4.1 <a class="header-anchor" href="#_0-4-1" aria-label="Permalink to “0.4.1”">​</a></h2><ul><li>adding LineFlags definitions contributed by @d-beamon into index.d.ts</li><li>merging a performance improvement contributed by @alessandromrc</li><li>got a good direction on how to use the gpiod-sim <a href="https://github.com/sombriks/node-libgpiod/issues/24" target="_blank" rel="noreferrer">https://github.com/sombriks/node-libgpiod/issues/24</a></li></ul><h2 id="_2024-02-24" tabindex="-1">2024-02-24 <a class="header-anchor" href="#_2024-02-24" aria-label="Permalink to “2024-02-24”">​</a></h2><h2 id="_0-4-0" tabindex="-1">0.4.0 <a class="header-anchor" href="#_0-4-0" aria-label="Permalink to “0.4.0”">​</a></h2><ul><li>Finally branched main into two distinct heads</li><li>Prepared a new virtual machine to be able to work with 1.x series</li><li>Still looking for a way to test the native part properly. There is [gpiomock][gpiomock] but i can&#39;t find it built on any distro i tried (opensuse/fedora). for 2.x there is gpio-sim, <strong>IF</strong> i figure out how to use it correctly.</li><li>This same log entry on main-2x will be different.</li></ul><h2 id="_2023-11-15" tabindex="-1">2023-11-15 <a class="header-anchor" href="#_2023-11-15" aria-label="Permalink to “2023-11-15”">​</a></h2><h3 id="_0-3-2" tabindex="-1">0.3.2 <a class="header-anchor" href="#_0-3-2" aria-label="Permalink to “0.3.2”">​</a></h3><ul><li>added new <code>Pin(n)</code> as a syntax sugar to get a new <code>Line(n)</code> from <code>Chip(0)</code>.</li><li>put the workflow to run tests but mostly are ignored for the moment. i am looking for a proper way to simulate a chip.</li></ul><h2 id="_2023-11-13" tabindex="-1">2023-11-13 <a class="header-anchor" href="#_2023-11-13" aria-label="Permalink to “2023-11-13”">​</a></h2><h3 id="_0-3-1" tabindex="-1">0.3.1 <a class="header-anchor" href="#_0-3-1" aria-label="Permalink to “0.3.1”">​</a></h3><ul><li>Merged PR #12 from @khill-fbmc fixing errors in index.d.ts</li><li>Some dependency version bumps, it compiles again under node 18.</li><li>Added GitHub Action to ease release process</li></ul><p>I&#39;ll try to streamline more the changes we receive, let me know if anything needs immediate attention.</p><h2 id="_2022-04-17" tabindex="-1">2022-04-17 <a class="header-anchor" href="#_2022-04-17" aria-label="Permalink to “2022-04-17”">​</a></h2><h3 id="_0-3-0" tabindex="-1">0.3.0 <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to “0.3.0”">​</a></h3><ul><li>Added Chip::getNumberOfLines which returns the number of available GPIO lines on the chip</li><li>Added Chip::getChipName which returns chip&#39;s name as represented by the kernel</li><li>Added Chip::getChipLabel which returns chip&#39;s label as represented by the kernel</li><li>Added Line::getLineOffset which returns line&#39;s offset number</li><li>Added Line::getLineName which returns line&#39;s name, if set, otherwise undefined</li><li>Added Line::getLineConsumer which returns line&#39;s consumer, if set, otherwise undefined</li><li>Extended the Typescript .d.ts file with the new methods and added jsdoc comments</li><li>Added a condition in the binding.gyp to prevent builds on non-Linux environments (aka macs or Windows machines)</li></ul><h2 id="_2022-04-15" tabindex="-1">2022-04-15 <a class="header-anchor" href="#_2022-04-15" aria-label="Permalink to “2022-04-15”">​</a></h2><h3 id="_0-2-2" tabindex="-1">0.2.2 <a class="header-anchor" href="#_0-2-2" aria-label="Permalink to “0.2.2”">​</a></h3><p>Fix for double line instantiation on same process contributed by <a href="https://github.com/dmitrydvorkin" target="_blank" rel="noreferrer">dmitrydvorkin</a></p><h2 id="_2022-03-11" tabindex="-1">2022-03-11 <a class="header-anchor" href="#_2022-03-11" aria-label="Permalink to “2022-03-11”">​</a></h2><p>created the changelog file so we can properly track changes and contributions</p><h3 id="_0-2-1" tabindex="-1">0.2.1 <a class="header-anchor" href="#_0-2-1" aria-label="Permalink to “0.2.1”">​</a></h3><p>Fixed argument index of consumer name on requestInputMode by <a href="https://github.com/noctarius" target="_blank" rel="noreferrer">noctarius</a></p><h2 id="_2022-03-09" tabindex="-1">2022-03-09 <a class="header-anchor" href="#_2022-03-09" aria-label="Permalink to “2022-03-09”">​</a></h2><h3 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to “0.2.0”">​</a></h3><p>code fix and type definitions contributed by <a href="https://github.com/noctarius" target="_blank" rel="noreferrer">noctarius</a></p><h2 id="_2020-12-30" tabindex="-1">2020-12-30 <a class="header-anchor" href="#_2020-12-30" aria-label="Permalink to “2020-12-30”">​</a></h2><h3 id="_0-1-4" tabindex="-1">0.1.4 <a class="header-anchor" href="#_0-1-4" aria-label="Permalink to “0.1.4”">​</a></h3><p>first really usable version. present on <a href="https://github.com/sombriks/node-libgpiod-examples" target="_blank" rel="noreferrer">node-libgpiod-examples</a></p><h2 id="_2020-12-17" tabindex="-1">2020-12-17 <a class="header-anchor" href="#_2020-12-17" aria-label="Permalink to “2020-12-17”">​</a></h2><h3 id="_0-0-1" tabindex="-1">0.0.1 <a class="header-anchor" href="#_0-0-1" aria-label="Permalink to “0.0.1”">​</a></h3><p>initial release on npm</p>',53)])])}const b=a(n,[["render",o]]);export{p as __pageData,b as default};
